#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "clip_hierarchy.h"
#include "channel_binding.h"
#include <map>
int main(int argc,char**argv){try{if(argc!=2)return 1;auto g=loadGraph(argv[1]);std::map<std::string,unsigned>counts;std::map<std::pair<uint32_t,std::string>,unsigned>sources,destinations;for(uint32_t id=0;id<g.elements.size();++id){if(g.strings[g.elements[id].type]!="DmeChannel")continue;ChannelBinding b(g,id);auto type=b.destination.scalarType;if(type!=10&&type!=13)continue;std::string from=b.source.present()?g.strings[g.elements[b.source.element].type]+":"+b.source.attribute:"absent";std::string to=b.destination.present()?g.strings[g.elements[b.destination.element].type]+":"+b.destination.attribute:"absent";counts[std::to_string(type)+" mode="+std::to_string(b.mode)+" "+from+" -> "+to]++;if(b.source.present())sources[{b.source.element,b.source.attribute}]++;if(b.destination.present())destinations[{b.destination.element,b.destination.attribute}]++;}for(auto&row:counts)std::cout<<row.second<<" "<<row.first<<std::endl;std::map<std::string,unsigned>constraintTypes;for(const auto&e:g.elements){auto type=g.strings[e.type];if(type.find("Constraint")!=std::string::npos){++constraintTypes[type];if(constraintTypes[type]==1){std::cout<<"constraint_schema "<<type;for(const auto&a:e.attributes)std::cout<<" "<<g.strings[a.name]<<":"<<unsigned(a.type);std::cout<<std::endl;}}}for(const auto&entry:constraintTypes)std::cout<<"constraint_count "<<entry.first<<"="<<entry.second<<std::endl;unsigned shared=0;for(auto&row:sources)if(destinations.count(row.first))++shared;std::cout<<"shared_source_destination_attributes="<<shared<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
